// 参数必须显式指向原欠期和原钱袋；不会用执行权替本人选择扣款或自动复业。
#include "private_shop_daily_rent_boundary.hpp"
#include "resident/domains/local_economy/economic_payload_guard.hpp"
#include "resident/kernel/command_types.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <map>
namespace hanmo::resident {
// 格式门只验两种真实零时回执形状，实际来源和永久结果绑定仍由完整冷账验证。
Status validate_private_shop_daily_rent_receipt(const StableId& kind,const ReceiptDetails& details){const auto* effect=std::get_if<InteractionEffect>(&details.data);const auto prefix=kind=="private_shop_pay_rent_arrear"?private_shop_rent_paid_kind:private_shop_rent_resumed_kind;if(!private_shop_daily_rent_command_kind(kind)||!effect||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids||!organization_instance_sequence(effect->settlement_result,prefix))return common_failure("InvalidPrivateShopRentReceipt");return common_success();}
StableId private_shop_daily_rent_command_kind(const PrivateShopDailyRentCommand& command){return std::holds_alternative<PrivateShopPayRentArrear>(command)?"private_shop_pay_rent_arrear":"private_shop_resume_rent";}
Outcome<PrivateShopDailyRentCommand> decode_private_shop_daily_rent_command(const StableId& kind,const BoundaryValue& params){auto unique=validate_economic_payload_fields(params);if(!unique.ok)return {false,{},unique.error};try{using namespace boundary;
 if(kind=="private_shop_pay_rent_arrear"){fields(params,{"shop_id","assessment_fact_id","payer_wallet_id","mandate_fact_id","death_notice_binding_fact_id"},{},kind);PrivateShopPayRentArrear c{get_string(params,"shop_id",kind),get_string(params,"assessment_fact_id",kind),get_string(params,"payer_wallet_id",kind),get_string(params,"mandate_fact_id",kind),get_string(params,"death_notice_binding_fact_id",kind)};if(c.shop_id.empty()||c.assessment_fact_id.empty()||c.payer_wallet_id.empty()||c.mandate_fact_id.empty()!=c.death_notice_binding_fact_id.empty())fail("InvalidPrivateShopRentCommand",kind);return {true,std::move(c),{}};}
 if(kind=="private_shop_resume_rent"){fields(params,{"shop_id"},{},kind);auto id=get_string(params,"shop_id",kind);if(id.empty())fail("InvalidPrivateShopRentCommand",kind);return {true,PrivateShopResumeRent{id},{}};}
 fail("UnknownPrivateShopDailyRentCommand",kind);
 }catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_private_shop_daily_rent_command(const PrivateShopDailyRentCommand& command){using V=BoundaryValue;if(const auto* c=std::get_if<PrivateShopPayRentArrear>(&command))return boundary::obj({{"shop_id",V{c->shop_id}},{"assessment_fact_id",V{c->assessment_fact_id}},{"payer_wallet_id",V{c->payer_wallet_id}},{"mandate_fact_id",V{c->mandate_fact_id}},{"death_notice_binding_fact_id",V{c->death_notice_binding_fact_id}}});return boundary::obj({{"shop_id",V{std::get<PrivateShopResumeRent>(command).shop_id}}});}
BoundaryValue encode_private_shop_daily_rent_quote(const PrivateShopDailyRentQuote& q){using V=BoundaryValue;return boundary::obj({{"ok",V{true}},{"kind",V{private_shop_daily_rent_command_kind(q.command)}},{"actor_id",V{q.actor_id}},{"params",encode_private_shop_daily_rent_command(q.command)},{"terms",boundary::obj({{"duration",V{Integer{0}}},{"shop_id",V{q.shop_id}},{"assessment_fact_id",V{q.assessment_fact_id}},{"arrear_id",V{q.arrear_id}},{"from_wallet_id",V{q.from_wallet_id}},{"to_wallet_id",V{q.to_wallet_id}},{"amount",V{q.amount}},{"period_index",V{q.period_index}},{"from_tick",V{q.from_tick}},{"through_tick",V{q.through_tick}},{"effect",V{StableId{std::holds_alternative<PrivateShopPayRentArrear>(q.command)?"只偿清这一原欠期；店铺仍暂停，继续占铺须原店主另行复业。":"明确启用本期占铺；暂停空档不补计，未足整期仍按冻结整期租金。"}}}})}});}
Status validate_private_shop_daily_rent_pair(bool enabled,const std::vector<std::pair<StableId,StableId>>& modules){std::map<StableId,StableId> chosen;for(const auto& row:modules)if(row.first==private_shop_daily_rent_module||(enabled&&row.first==private_shop_module)){if(row.second!="1"||!chosen.emplace(row).second)return common_failure("PrivateShopDailyRentPairMismatch",row.first);}if(enabled!=bool(chosen.count(private_shop_daily_rent_module))||(enabled&&!chosen.count(private_shop_module)))return common_failure("PrivateShopDailyRentPairMismatch");return common_success();}
}
